// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // Fuzz the caller address so fuzzer can find an address to call from (EOA)
    // and fuzz an array length possibility by providing a bytes parameter that we decode to an address[]
    // We need at least one fuzz parameter; use bytes data to construct an address[] that can be empty.
    function testFuzz_property(address from, uint256 v, bytes memory tosRaw) public {
        // Build an address[] from tosRaw: interpret each 20-byte chunk as an address.
        // This lets the fuzzer produce empty arrays (when tosRaw.length < 20) and non-empty ones.
        uint256 chunks = tosRaw.length / 20;
        address[] memory tos = new address[](chunks);
        for (uint256 i = 0; i < chunks; i++) {
            uint256 offset = i * 20;
            bytes20 b;
            assembly {
                b := mload(add(add(tosRaw, 0x14), offset))
            }
            tos[i] = address(b);
        }

        // We will call c.transfer and observe whether it returns (succeeds) or reverts.
        // The reference C requires _tos.length > 0 and thus must revert for empty tos.
        bool ok;
        try c.transfer(from, address(this), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assert): For every admissible input, if tos is empty then transfer MUST revert (ok == false).
        // This holds for the reference contract but the mutant that deletes the require will sometimes return true (ok == true).
        if (tos.length == 0) {
            assertTrue(!ok);
        }
        // If tos.length > 0 we make no claim (do not restrict domain further).
    }
}
